-- Textos descriptivos por grupo muscular (editables por el monitor)
update public.exercises x set
  description_ca = 'Exercici de ' || lower(x.primary_muscle) || ' amb ' || lower(x.equipment) || '.',
  description_es = 'Ejercicio de ' || lower(x.primary_muscle) || ' con ' || lower(x.equipment) || '.',
  tips_ca = t.tc, tips_es = t.te, mistakes_ca = t.mc, mistakes_es = t.me
from (values
('Pit','Omoplats juntes i cap avall; el pit sempre alt.','Escápulas juntas y hacia abajo; pecho siempre alto.','Rebotar la barra al pit o obrir massa els colzes.','Rebotar la barra en el pecho o abrir demasiado los codos.'),
('Esquena','Inicia el moviment portant les omoplats enrere.','Inicia el movimiento llevando las escápulas hacia atrás.','Balancejar el tronc per ajudar-se amb l''impuls.','Balancear el tronco para ayudarse con impulso.'),
('Espatlles','Cos estable i abdomen contret; no arquejar la lumbar.','Cuerpo estable y abdomen contraído; no arquear la lumbar.','Pujar les espatlles cap a les orelles.','Subir los hombros hacia las orejas.'),
('Bíceps','Colzes fixos al costat del cos.','Codos fijos junto al cuerpo.','Fer trampa amb l''esquena per pujar més pes.','Hacer trampa con la espalda para subir más peso.'),
('Tríceps','Colzes tancats i fixos; només es mou l''avantbraç.','Codos cerrados y fijos; solo se mueve el antebrazo.','Obrir els colzes i perdre tensió.','Abrir los codos y perder tensión.'),
('Quàdriceps','Genolls alineats amb la punta dels peus.','Rodillas alineadas con la punta de los pies.','Deixar que els genolls es juntin en pujar.','Dejar que las rodillas se junten al subir.'),
('Isquiotibials','Esquena neutra; el moviment surt del maluc.','Espalda neutra; el movimiento sale de la cadera.','Arrodonir la lumbar o bloquejar genolls.','Redondear la lumbar o bloquear las rodillas.'),
('Glutis','Contrau els glutis a dalt i fes una pausa d''un segon.','Contrae los glúteos arriba y pausa un segundo.','Hiperextensió lumbar al final.','Hiperextensión lumbar al final.'),
('Panxells','Recorregut complet: baixa fins a estirar i puja fins a dalt.','Recorrido completo: baja hasta estirar y sube del todo.','Fer rebots curts sense control.','Hacer rebotes cortos sin control.'),
('Abdomen','Respira i contrau l''abdomen; no estiris del coll.','Respira y contrae el abdomen; no tires del cuello.','Estirar el cap amb les mans o deixar caure la lumbar.','Tirar de la cabeza con las manos o dejar caer la lumbar.'),
('Cardio','Ritme sostenible; mantén una postura recta.','Ritmo sostenible; mantén una postura recta.','Agafar-se amb força a les barres de la màquina.','Agarrarse con fuerza a las barras de la máquina.'),
('Cos complet','Tècnica abans que velocitat; pes moderat.','Técnica antes que velocidad; peso moderado.','Perdre l''esquena neutra sota fatiga.','Perder la espalda neutra bajo fatiga.')
) as t(muscle, tc, te, mc, me) where t.muscle = x.primary_muscle;

-- Usuarios (auth). El trigger crea profiles + member_details. Contrasenya demo: Demo1234!
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change, email_change_token_new)
